-- 托业全量词库迁移(v0.16.2 之后):0 → 2402 词,含三门互动课补建
-- 词表:三个公开托业词表并集(墨墨 TOEIC 990 核心词汇 1378 + Pass the TOEIC Test 官方册 1041
--       + toeic-600 话题词集 562),去重后 2402 词(26 字母单词;多词短语/连字符条目未收录,
--       App 拼写键盘仅 26 字母)。与 KET 重叠 226 词按托业商务语境重新生成义项,共享 lexeme_id。
-- 幂等:courses WHERE NOT EXISTS;lexicon 按 spelling 去重;words 按 (course_id, spelling) 去重。

-- 1. 补建「英语·托业·学习/测评」两门课(朗读课已存在;sort 沿用朗读 176 之后)
INSERT INTO courses (id, subject, textbook, learning_method, default_points, is_active, sort_order, created_at, updated_at)
SELECT gen_random_uuid(), '英语', '托业', m, p, TRUE, 177, now(), now()
FROM (VALUES ('学习', 5), ('测评', 15)) AS v(m, p)
WHERE NOT EXISTS (SELECT 1 FROM courses WHERE subject='英语' AND textbook='托业' AND learning_method=v.m);

-- 2. 激活托业三门互动课(朗读/学习/测评)
UPDATE courses SET is_active = TRUE, updated_at = NOW()
WHERE subject = '英语' AND textbook = '托业' AND learning_method IN ('朗读', '学习', '测评') AND is_active = FALSE;

