('vested', '["vest", "ed"]', '既得的;被授予的', '/ˈves.tɪd/', 'Employees become fully vested after five years of service.', '员工服务满五年后可获得全部既得权益。', 2335),
('vibrate', '["vi", "brate"]', '振动;颤动', '/vaɪˈbreɪt/', 'The old machines vibrate loudly during every production shift.', '旧机器在每个生产班次中都振动得很厉害。', 2336),
('vicious', '["vi", "cious"]', '恶意的;猛烈的', '/ˈvɪʃ.əs/', 'A vicious rumor about layoffs spread through the office.', '关于裁员的恶意谣言在办公室里传开了。', 2337),
('victim', '["vic", "tim"]', '受害者;牺牲品', '/ˈvɪk.tɪm/', 'The company compensated victims of the data breach.', '公司对数据泄露事件的受害者进行了赔偿。', 2338),
('vigor', '["vig", "or"]', '活力;精力', '/ˈvɪɡ.ər/', 'She approaches every new project with remarkable vigor.', '她以非凡的干劲对待每个新项目。', 2339),
('vilify', '["vil", "i", "fy"]', '诽谤;中伤', '/ˈvɪl.ɪ.faɪ/', 'Rivals tried to vilify the firm after the scandal.', '丑闻发生后，竞争对手试图诋毁这家公司。', 2340),
('vindicate', '["vin", "di", "cate"]', '证明…清白;证实', '/ˈvɪn.dɪ.keɪt/', 'The audit vindicated the accountant''s careful record keeping.', '审计证明了这位会计师细致的记账没有问题。', 2341),
('violate', '["vi", "o", "late"]', '违反;侵犯', '/ˈvaɪ.ə.leɪt/', 'Sharing passwords violates our information security policy.', '共享密码违反我们的信息安全政策。', 2342),
('virtual', '["vir", "tu", "al"]', '虚拟的;事实上的', '/ˈvɜː.tʃu.əl/', 'The team held a virtual meeting across three time zones.', '团队跨三个时区召开了线上会议。', 2343),
('virus', '["virus"]', '病毒', '/ˈvaɪ.rəs/', 'A virus infected several computers in the sales office.', '病毒感染了销售办公室的多台电脑。', 2344),
('vital', '["vi", "tal"]', '至关重要的', '/ˈvaɪ.təl/', 'Good communication is vital to a successful project.', '良好的沟通对项目成功至关重要。', 2345),
('vivacious', '["vi", "va", "cious"]', '活泼的;充满活力的', '/vɪˈveɪ.ʃəs/', 'Her vivacious manner makes her an excellent host for client events.', '她活泼的举止使她成为客户活动的出色主持人。', 2346),
('void', '["void"]', '无效的;使作废', '/vɔɪd/', 'The warranty becomes void if the seal is broken.', '封条破损则保修失效。', 2347),
('voltage', '["volt", "age"]', '电压', '/ˈvəʊl.tɪdʒ/', 'Check the voltage before plugging in the equipment.', '插上电源前请检查设备的电压。', 2348),
('volume', '["vol", "ume"]', '数量;音量;卷', '/ˈvɒl.juːm/', 'Sales volume increased sharply during the holiday season.', '假日季销量大幅增长。', 2349),
('volunteer', '["vol", "un", "teer"]', '志愿者;自愿做', '/ˌvɒl.ənˈtɪər/', 'Staff volunteered to organize the annual charity event.', '员工自愿组织年度慈善活动。', 2350),
('vulnerable', '["vul", "ner", "a", "ble"]', '脆弱的;易受攻击的', '/ˈvʌl.nər.ə.bəl/', 'Small suppliers are vulnerable to sudden price increases.', '小供应商容易受到价格突然上涨的冲击。', 2351),
('wade', '["wade"]', '涉水;费力处理', '/weɪd/', 'He waded through hundreds of emails after his vacation.', '假期后他费力地处理了数百封邮件。', 2352),
('wage', '["wage"]', '工资;发动', '/weɪdʒ/', 'The factory raised the minimum wage for all workers.', '工厂提高了所有工人的最低工资。', 2353),
('walkout', '["walk", "out"]', '罢工;退场抗议', '/ˈwɔːk.aʊt/', 'Workers staged a walkout to protest unsafe conditions.', '工人举行罢工，抗议不安全的工作条件。', 2354),
('walkway', '["walk", "way"]', '走道;人行道', '/ˈwɔːk.weɪ/', 'Keep the walkway clear of boxes and cables.', '请保持走道畅通，不要堆放箱子和电缆。', 2355),
('wallow', '["wal", "low"]', '沉溺;打滚', '/ˈwɒl.əʊ/', 'There is no time to wallow in past mistakes.', '没有时间沉湎于过去的错误。', 2356),
('wane', '["wane"]', '减弱;衰落', '/weɪn/', 'Interest in the product began to wane after summer.', '夏季过后人们对该产品的兴趣开始减退。', 2357),
('wanton', '["wan", "ton"]', '肆意的;无端的', '/ˈwɒn.tən/', 'The report criticized the wanton waste of company resources.', '报告批评了对公司资源的肆意浪费。', 2358),
('warehouse', '["ware", "house"]', '仓库', '/ˈweə.haʊs/', 'The new warehouse stores all of our imported goods.', '新仓库存放我们所有的进口货物。', 2359),
('warn', '["warn"]', '警告;提醒', '/wɔːn/', 'Analysts warn that fuel costs will rise this winter.', '分析师警告今年冬天燃料成本将上涨。', 2360),
('warning', '["warn", "ing"]', '警告;警示', '/ˈwɔː.nɪŋ/', 'He received a written warning for repeated lateness.', '他因多次迟到收到书面警告。', 2361),
('warrant', '["war", "rant"]', '使有必要;授权;令状', '/ˈwɒr.ənt/', 'The situation does not warrant such drastic measures.', '情况还没有严重到需要采取如此极端的措施。', 2362),
('warranty', '["war", "ran", "ty"]', '保修;质保', '/ˈwɒr.ən.ti/', 'The new laptop comes with a two-year warranty.', '这台新笔记本电脑附带两年保修。', 2363),
('wastage', '["wastage"]', '浪费;损耗', '/ˈweɪ.stɪdʒ/', 'Better planning reduced food wastage in the cafeteria.', '更好的规划减少了食堂的食物浪费。', 2364),
('waste', '["waste"]', '浪费;废物', '/weɪst/', 'The new policy aims to reduce paper waste.', '新政策旨在减少纸张浪费。', 2365),
('waterproof', '["wa", "ter", "proof"]', '防水的', '/ˈwɔː.tə.pruːf/', 'All outdoor equipment must be packed in waterproof bags.', '所有户外设备必须装在防水袋里。', 2366),
('wax', '["wax"]', '蜡;给…打蜡', '/wæks/', 'The cleaning crew will wax the lobby floor tonight.', '清洁队今晚将给大堂地板打蜡。', 2367),
('weakly', '["weak", "ly"]', '无力地;疲软地', '/ˈwiːk.li/', 'The market responded weakly to the product launch.', '市场对产品发布的反应平淡。', 2368),
('wealth', '["wealth"]', '财富;大量', '/welθ/', 'The report shows the growing wealth of the region.', '报告显示该地区日益增长的财富。', 2369),
('wear', '["wear"]', '穿着;磨损', '/weər/', 'Visitors must wear identification badges at all times.', '访客必须始终佩戴身份徽章。', 2370),
('weary', '["weary"]', '疲倦的;厌倦的', '/ˈwɪə.ri/', 'The team felt weary after months of overtime.', '数月加班后团队感到疲惫不堪。', 2371),
('weather', '["weath", "er"]', '天气;经受住', '/ˈweð.ər/', 'The company managed to weather the financial crisis.', '公司成功渡过了金融危机。', 2372),
('website', '["web", "site"]', '网站', '/ˈweb.saɪt/', 'Customers can track their orders on our website.', '客户可以在我们的网站上追踪订单。', 2373),
('wedded', '["wed", "ded"]', '执着的;已婚的', '/ˈwed.ɪd/', 'He remains wedded to the old way of working.', '他仍然执着于旧的工作方式。', 2374),
('weight', '["weight"]', '重量;分量', '/weɪt/', 'The shipment exceeded the maximum weight limit for trucks.', '这批货超过了卡车的最大重量限制。', 2375),
('welfare', '["wel", "fare"]', '福利;福祉', '/ˈwel.feər/', 'The company invests heavily in employee welfare programs.', '公司在员工福利项目上投入很大。', 2376),
('whisk', '["whisk"]', '快速送走;搅拌', '/wɪsk/', 'The courier whisked the documents to the client''s office.', '快递员迅速把文件送到了客户办公室。', 2377),
('wholesale', '["whole", "sale"]', '批发;批发的', '/ˈhəʊl.seɪl/', 'We buy all office paper at wholesale prices.', '我们以批发价购买所有办公用纸。', 2378),
('widespread', '["wide", "spread"]', '广泛的;普遍的', '/ˈwaɪd.spred/', 'The outage caused widespread disruption to online services.', '这次故障造成在线服务大范围中断。', 2379),
('win', '["win"]', '赢得;胜利', '/wɪn/', 'Our team hopes to win the contract this quarter.', '我们团队希望本季度赢得这份合同。', 2380),
('wisely', '["wise", "ly"]', '明智地', '/ˈwaɪz.li/', 'She invested the budget surplus wisely in staff training.', '她明智地把预算盈余投资于员工培训。', 2381),
('withdraw', '["with", "draw"]', '提取;撤回', '/wɪðˈdrɔː/', 'He decided to withdraw his application before the interview.', '他决定在面试前撤回申请。', 2382),
('withdrawal', '["with", "draw", "al"]', '提款;撤回', '/wɪðˈdrɔː.əl/', 'The bank charges a fee for each overseas withdrawal.', '银行对每笔海外取款收取手续费。', 2383),
('withhold', '["with", "hold"]', '扣留;拒绝给予', '/wɪðˈhəʊld/', 'The client decided to withhold payment until repairs were done.', '客户决定扣留货款，直到维修完成。', 2384),
('witness', '["wit", "ness"]', '目击;见证;证人', '/ˈwɪt.nəs/', 'Two managers witnessed the signing of the agreement.', '两位经理见证了协议的签署。', 2385),
('workaholic', '["worka", "holic"]', '工作狂', '/ˌwɜː.kəˈhɒl.ɪk/', 'My boss is a workaholic who answers emails at midnight.', '我的老板是个工作狂，半夜还在回邮件。', 2386),
('workforce', '["work", "force"]', '劳动力;员工总数', '/ˈwɜːk.fɔːs/', 'The company plans to expand its workforce next year.', '公司计划明年扩大员工队伍。', 2387),
('workplace', '["work", "place"]', '工作场所', '/ˈwɜːk.pleɪs/', 'Safety rules must be followed throughout the workplace.', '整个工作场所都必须遵守安全规定。', 2388),
('workshop', '["work", "shop"]', '研讨会;车间', '/ˈwɜːk.ʃɒp/', 'We attended a workshop on effective communication skills.', '我们参加了一个关于有效沟通技巧的研讨会。', 2389),
('worldly', '["world", "ly"]', '阅历丰富的;世俗的', '/ˈwɜːld.li/', 'Her worldly business experience impressed the entire interview panel.', '她丰富的商界阅历给整个面试小组留下了深刻印象。', 2390),
('worth', '["worth"]', '价值;值得', '/wɜːθ/', 'The deal is worth nearly two million dollars.', '这笔交易价值近两百万美元。', 2391),
('worthless', '["worth", "less"]', '无价值的;没用的', '/ˈwɜːθ.ləs/', 'The outdated stock certificates are now completely worthless.', '那些过时的股票凭证现在一文不值。', 2392),
('wrap', '["wrap"]', '包裹;完成', '/ræp/', 'Please wrap the fragile items before shipping them.', '请在发货前把易碎物品包好。', 2393),
('wreak', '["wreak"]', '造成(破坏);发泄', '/riːk/', 'The storm wreaked havoc on the delivery network.', '暴风雨给配送网络造成了严重破坏。', 2394),
('wrinkle', '["wrin", "kle"]', '皱纹;皱褶', '/ˈrɪŋ.kəl/', 'Iron your shirt to remove the wrinkles before the meeting.', '开会前把衬衫的皱褶熨平。', 2395),
('yearly', '["year", "ly"]', '每年的;一年一次的', '/ˈjɪə.li/', 'All staff members receive a yearly performance review.', '所有员工每年接受一次绩效考核。', 2396),
('yield', '["yield"]', '产出;收益;让步', '/jiːld/', 'The investment yielded a ten percent return last year.', '这项投资去年产生了百分之十的回报。', 2397),
('youth', '["youth"]', '青年;青春', '/juːθ/', 'The program trains local youth for technical careers.', '该项目培训当地青年从事技术职业。', 2398),
('zealous', '["zeal", "ous"]', '热心的;热忱的', '/ˈzel.əs/', 'A zealous sales team can double annual revenue.', '一支充满热忱的销售团队可以让年收入翻倍。', 2399),
('zenith', '["zenith"]', '顶峰;顶点', '/ˈzen.ɪθ/', 'The company reached its zenith in the late nineties.', '这家公司在九十年代末达到了顶峰。', 2400),
('zero', '["ze", "ro"]', '零', '/ˈzɪə.rəʊ/', 'The report found zero defects in the final inspection.', '报告在最终检验中发现零缺陷。', 2401),
('zone', '["zone"]', '区域;地带', '/zəʊn/', 'The factory is located in a special economic zone.', '工厂位于一个经济特区内。', 2402)
) AS v(spelling, syllables, meaning_cn, phonetic, sample_sentence, sample_sentence_translation, sort_order)
JOIN courses c ON c.subject = '英语' AND c.textbook = '托业' AND c.learning_method IN ('朗读', '学习', '测评') AND c.is_active = TRUE
JOIN lexicon l ON l.spelling = v.spelling
WHERE NOT EXISTS (SELECT 1 FROM words x WHERE x.course_id = c.id AND x.spelling = v.spelling);
